// The site's data, generated by scripts/build_site_data.py from results/manifest.json. Every number
// on a page is a manifest value already formatted by the code the documents use.
import raw from "@/data/site.json";

export type Table = { columns: string[]; align: ("left" | "right")[]; rows: string[][]; source: string; origin: string };
export type Point = { x: number; y: number; lo: number; hi: number };
export type Series = { model: string; name: string; color: string; points: Point[]; op: Point };
export type Desk = { budget: number; models: Series[]; champion: string | null };
export type Expected = { event_ref: number; score: number; verdict: string; codes: string[] };
export type ReplayDesk = { model: string; events: Record<string, unknown>[]; recorded: Expected[] };
export type Alert = { check: string; scope: string; value: number; threshold: number; severity: string; note: string };

type Site = {
  statement: string;
  as_of: string;
  values: Record<string, string>;
  tables: Record<string, Table>;
  frontier: Record<string, Desk> | null;
  replay: Record<string, ReplayDesk>;
  classification: { table: string; column: string; classification: string; says: string }[];
  monitor: { alerts: Alert[]; maturity: Record<string, number | string>[] } | null;
  parity: Record<string, unknown> | null;
};

export const site = raw as unknown as Site;

export function v(key: string): string {
  return site.values[key] ?? "not measured yet";
}

export function has(key: string): boolean {
  return key in site.values || key in site.tables;
}

export function table(key: string): Table | null {
  return site.tables[key] ?? null;
}

export const API = process.env.NEXT_PUBLIC_FRICTION_API ?? "";
